-- Car search (spec §5.1, decided 2026-11-14). Both new columns are generated by Postgres
-- from the row itself, so every write path stays correct and the app never sets them.
-- Prisma knows them as @default(dbgenerated()).

-- Public map position: the exact location moved by a fixed offset derived from the car
-- id (md5), so it does not change between requests and averaging reveals nothing. The
-- offset is 200 m to 1 km, spread evenly over that ring; the web app draws a 1 km circle
-- around it, which always contains the car. 111 320 m per degree of latitude.
ALTER TABLE "cars"
  ADD COLUMN "approx_latitude" DECIMAL(9,6) NOT NULL GENERATED ALWAYS AS (
    round((
      "latitude"::float8
      + 1000 * sqrt(0.04 + 0.96 * (('x' || substr(md5("id"::text), 9, 8))::bit(32)::bigint / 4294967296.0))
        * cos(2 * pi() * (('x' || substr(md5("id"::text), 1, 8))::bit(32)::bigint / 4294967296.0))
        / 111320
    )::numeric, 6)
  ) STORED,
  ADD COLUMN "approx_longitude" DECIMAL(9,6) NOT NULL GENERATED ALWAYS AS (
    round((
      "longitude"::float8
      + 1000 * sqrt(0.04 + 0.96 * (('x' || substr(md5("id"::text), 9, 8))::bit(32)::bigint / 4294967296.0))
        * sin(2 * pi() * (('x' || substr(md5("id"::text), 1, 8))::bit(32)::bigint / 4294967296.0))
        / (111320 * cos(radians("latitude"::float8)))
    )::numeric, 6)
  ) STORED;

-- Search filters and sorts by approximate position only, so results never reveal more
-- than the map does. The exact-position index had no reader.
DROP INDEX "cars_latitude_longitude_idx";
CREATE INDEX "cars_approx_latitude_approx_longitude_idx" ON "cars"("approx_latitude", "approx_longitude");

-- What one day costs, for the price filter and sort: the daily price, else the lower of
-- 24 × hourly and monthly ÷ 30 rounded to 1.000đ (LEAST skips the unit that is off).
ALTER TABLE "car_pricings"
  ADD COLUMN "daily_equivalent_price" INTEGER NOT NULL GENERATED ALWAYS AS (
    COALESCE(
      "daily_price",
      LEAST("hourly_price" * 24, (round("monthly_price" / 30000.0) * 1000)::integer)
    )
  ) STORED;

CREATE INDEX "car_pricings_daily_equivalent_price_idx" ON "car_pricings"("daily_equivalent_price");
